int main(){
    vector<vector<double>>x={{1,2},{2,4},{3,6}};
    vector<double>direction={1/sqrt(5.0),2/sqrt(5.0)};
    double error=0;
    for (const auto& row:x){
        double score=row[0]*direction[0]+row[1]*direction[1];
        for (int i=0;i<2;i++)error+=pow(row[i]-score*direction[i],2);
    }
    cout<<fixed<<setprecision(10)<<error<<"\n";
    return 0;
}

