#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
    vector<int>count={2,1,1};
    vector<double>p={0.5,0.3,0.2};
    int n=0;
    double logProbability=0;
    for (int x:count)n+=x;
    double logMultinomial=lgamma(n+1);
    for (int i=0;i<int(count.size());i++){
        logMultinomial-=lgamma(count[i]+1);
        logProbability+=count[i]*log(p[i]);
    }
    cout<<fixed<<setprecision(8)<<exp(logMultinomial+logProbability)<<"\n";
    return 0;
}

