int main(){
    double x=5,rate=0.1,previous=1e100;
    for (int step=0;step<200;step++){
        double loss=pow(x-3,2),gradient=2*(x-3);
        if (fabs(gradient)<1e-6||fabs(previous-loss)<1e-10){
            cout<<"stop "<<step<<"\n";
            break;
        }
        previous=loss;
        x-=rate*gradient;
    }
    return 0;
}

